import{isPro}from"../common/other-tools.js";import{verify}from"../common/captcha.js";import{verifyToken}from"../service/token.js";import{PublicReturn}from"../common/public-return.js";export async function vToken(e,n){const o=e.headers||{},r=String(o.token||""),t=verifyToken(r);t.state?e.userInfo=t:n.code(401).send(new PublicReturn(401,t.msg||"凭证无效"))}export async function vAdmin(e,n){const o=e.headers||{},r=String(o.token||""),t=verifyToken(r);t.state?"admin"===t.userRole?e.userInfo=t:n.code(403).send(new PublicReturn(403,"权限不足")):n.code(401).send(new PublicReturn(401,t.msg||"凭证无效"))}export async function vCaptcha(e,n){if(!isPro())return;const o=e.body||{},r=o.captchaId,t=o.captchaText;if(!r||!t)return void n.code(400).send(new PublicReturn(400,"请携带验证码信息"));verify(r,t)||n.code(400).send(new PublicReturn(400,"验证码验证失败 || 验证码过期"))}